from backtester import Strategy

class MyStrategy(Strategy):
    def init(self, ctx):
        self.sma_10 = None
        self.sma_30 = None
        self.position = None

    def on_bar(self, ctx):
        if ctx.history().shape[0] < 30:
            return

        close = ctx.history()['close']
        self.sma_10 = close.rolling(window=10).mean().iloc[-1]
        self.sma_30 = close.rolling(window=30).mean().iloc[-1]

        if self.sma_10 > self.sma_30 and self.position is None:
            ctx.order_target_percent(0.95)
            self.position = 'long'
        elif self.sma_10 < self.sma_30 and self.position == 'long':
            ctx.close_position()
            self.position = None

strategy = MyStrategy()

