class TimeSeriesMomentum(Strategy):
    def init(self, ctx):
        self.lookback = 60
        self.required_history = self.lookback + 1

    def on_bar(self, ctx):
        if ctx.history().shape[0] < self.required_history:
            return

        current_close = ctx.price()
        sixty_day_close = ctx.history().iloc[-self.lookback]['close']

        if current_close > sixty_day_close:
            ctx.order_target_percent(0.95)
        else:
            ctx.order_target_percent(0)

strategy = TimeSeriesMomentum()

from backtester import Strategy

class MyStrategy(Strategy):
    def on_bar(self, ctx):
        if len(ctx.history()) < 10:
            return

        current_close = ctx.price()
        lowest_close = ctx.history()['close'].min()

        if current_close == lowest_close:
            ctx.order_target_percent(0.95)

        if ctx.position() > 0 and ctx.timestamp.dayofweek == 4 and ctx.timestamp.hour == 16:
            ctx.close_position()

strategy = MyStrategy()

