class WeekendEffectStrategy(Strategy):
    def on_bar(self, ctx):
        if ctx.timestamp.weekday() == 4:  # Friday
            if ctx.position() == 0:
                ctx.order_target_percent(0.95)
        elif ctx.timestamp.weekday() == 0:  # Monday
            if ctx.position() > 0:
                ctx.close_position()

strategy = WeekendEffectStrategy()

from backtester import Strategy

class EqualWeightPortfolio(Strategy):
    def __init__(self):
        self.rebalance_count = 0

    def init(self, ctx):
        self.symbols = ['AAA', 'BBB', 'CCC']

    def on_bar(self, ctx):
        if ctx.timestamp.day == 1 or ctx.timestamp.day % 20 == 1:
            self.rebalance_count += 1
            for symbol in self.symbols:
                ctx.order_target_percent(0.3, symbol)

strategy = EqualWeightPortfolio()
